import{_ as n,o as i,c as e,a3 as t}from"./chunks/framework.BvvarXmc.js";const d=JSON.parse('{"title":"Cara Cek & Bayar Tagihan SPP Online","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-siswa/cek-bayar-spp.md","filePath":"panduan-siswa/cek-bayar-spp.md","lastUpdated":null}'),l={name:"panduan-siswa/cek-bayar-spp.md"};function r(s,a,o,u,k,m){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="cara-cek-bayar-tagihan-spp-online" tabindex="-1">Cara Cek &amp; Bayar Tagihan SPP Online <a class="header-anchor" href="#cara-cek-bayar-tagihan-spp-online" aria-label="Permalink to &quot;Cara Cek &amp; Bayar Tagihan SPP Online&quot;">​</a></h1><p>Orang tua siswa dapat mengecek status pembayaran dan melunasi kewajiban sekolah secara online kapan saja tanpa perlu datang ke sekolah.</p><hr><h2 id="_1-mengecek-daftar-tagihan" tabindex="-1">1. Mengecek Daftar Tagihan <a class="header-anchor" href="#_1-mengecek-daftar-tagihan" aria-label="Permalink to &quot;1. Mengecek Daftar Tagihan&quot;">​</a></h2><ol><li>Setelah masuk ke portal siswa, pilih menu <strong>Tagihan Saya (Bills)</strong> di bilah menu samping.</li><li>Anda akan melihat ringkasan: <ul><li><strong>Total Tagihan Belum Dibayar</strong>.</li><li>Kartu daftar bulan SPP (misal: <em>SPP Juli - LUNAS</em>, <em>SPP Agustus - BELUM DIBAYAR</em>).</li><li>Tagihan non-SPP seperti Uang Kegiatan, Uang Buku, atau Uang Gedung.</li></ul></li></ol><hr><h2 id="_2-cara-melakukan-pembayaran-via-virtual-account-bank" tabindex="-1">2. Cara Melakukan Pembayaran via Virtual Account Bank <a class="header-anchor" href="#_2-cara-melakukan-pembayaran-via-virtual-account-bank" aria-label="Permalink to &quot;2. Cara Melakukan Pembayaran via Virtual Account Bank&quot;">​</a></h2><ol><li>Beri centang pada satu atau beberapa bulan tagihan yang ingin dibayarkan.</li><li>Klik tombol <strong>Bayar Tagihan Terpilih</strong>.</li><li>Pilih metode pembayaran bank: <ul><li><strong>Bank BNI Virtual Account</strong></li><li><strong>Bank BRI Virtual Account</strong></li><li><em>(Atau bank lain yang tersedia di sekolah Anda)</em></li></ul></li><li>Klik <strong>Lanjutkan Pembayaran</strong>.</li><li>Layar akan menampilkan <strong>Nomor Virtual Account</strong> (contoh: <code>9881 0051 2345 6789</code>) dan batas waktu transfer.</li><li>Salin nomor VA tersebut, lalu lakukan transfer dari aplikasi m-Banking, ATM, atau Internet Banking Anda: <ul><li>Pilih menu <strong>Transfer / Bayar Virtual Account</strong>.</li><li>Masukkan nomor VA tersebut.</li><li>Nama siswa dan nominal otomatis akan muncul di layar ATM/m-Banking.</li><li>Konfirmasi pembayaran.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Verifikasi Otomatis</p><p>Setelah Anda menekan tombol transfer di bank, status tagihan di portal sekolah akan otomatis berubah menjadi <strong>LUNAS</strong> dalam hitungan detik. Kuitansi pembayaran digital langsung diterbitkan dan dapat diunduh sebagai file PDF.</p></div>',9)])])}const g=n(l,[["render",r]]);export{d as __pageData,g as default};
